import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.B7wGsJGy.js";const b=JSON.parse('{"title":"Node.js 学习入口","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/05node/intro.md","filePath":"概念与原理/05node/intro.md","lastUpdated":1794382705000}'),r={name:"概念与原理/05node/intro.md"};function d(o,a,p,l,i,c){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="node-js-学习入口" tabindex="-1">Node.js 学习入口 <a class="header-anchor" href="#node-js-学习入口" aria-label="Permalink to &quot;Node.js 学习入口&quot;">​</a></h1><blockquote><p>从前端 JavaScript 走向服务端：理解代码在什么环境中运行、请求如何并发处理，以及文件、网络、资源与依赖如何管理。本模块按原有四项大纲整理，示例以 Node.js 24 为学习基线。</p></blockquote><h2 id="一、先建立运行时的认识" tabindex="-1">一、先建立运行时的认识 <a class="header-anchor" href="#一、先建立运行时的认识" aria-label="Permalink to &quot;一、先建立运行时的认识&quot;">​</a></h2><p><strong>Node.js 是基于 V8 的 JavaScript 运行时，不是语言，也不是 Web 框架。</strong> V8 负责执行 JavaScript，Node.js 提供文件、网络、进程等服务端能力，libuv 等底层组件参与事件循环和异步 I/O 调度。</p><table tabindex="0"><thead><tr><th>层次</th><th>解决的问题</th><th>示例</th></tr></thead><tbody><tr><td>JavaScript / TypeScript</td><td>用什么语言描述逻辑</td><td>Promise、类型、模块语法；TS 通常还需要类型检查和转换</td></tr><tr><td>Node.js</td><td>代码在哪里执行，如何使用系统能力</td><td>文件、HTTP、Stream、进程、事件循环</td></tr><tr><td>Express / Koa / Fastify</td><td>如何组织 Web 请求处理</td><td>路由、中间件、请求与响应</td></tr><tr><td>NestJS</td><td>如何组织服务端应用架构</td><td>Module、Controller、Provider、DI、Guard</td></tr></tbody></table><p>浏览器和 Node.js 都能执行 JavaScript，但宿主 API 不同：Node.js 没有浏览器 DOM，浏览器不能直接使用 <code>node:fs</code>。Node.js 也提供部分 Web API，例如 <code>fetch</code>，因此不能简单用“有没有 fetch”区分二者。</p><h2 id="二、建议按这个顺序学习" tabindex="-1">二、建议按这个顺序学习 <a class="header-anchor" href="#二、建议按这个顺序学习" aria-label="Permalink to &quot;二、建议按这个顺序学习&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>学完应该能解释什么</th></tr></thead><tbody><tr><td>1</td><td><a href="./s_node_1-core_modules">常用模块与资源管理</a></td><td>ESM/CJS、文件与路径、Buffer、Stream、事件和错误处理</td></tr><tr><td>2</td><td><a href="./s_node_2-event_loop">事件循环与异步并发</a></td><td>单线程为何能处理多个请求、微任务与事件循环、CPU 密集任务的边界</td></tr><tr><td>3</td><td><a href="./s_node_3-http_koa">HTTP 服务与 Koa 洋葱模型</a></td><td>原生 HTTP 如何工作、中间件如何组合、Express/Koa/NestJS 各负责什么</td></tr><tr><td>4</td><td><a href="./s_node_4-package_management">npm、Yarn、pnpm 与依赖管理</a></td><td>package.json、版本范围、锁文件、依赖布局与可重复安装</td></tr></tbody></table><p>每篇按“概念 → 示例 → 工程边界 → 学习回顾”展开。先理解最小机制，再通过框架承接重复工作，最后验证异常和资源边界。</p><h2 id="三、用一次请求串起知识点" tabindex="-1">三、用一次请求串起知识点 <a class="header-anchor" href="#三、用一次请求串起知识点" aria-label="Permalink to &quot;三、用一次请求串起知识点&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端发送 HTTP 请求</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Node.js 接收网络事件，触发请求处理逻辑</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>框架进行路由、中间件处理，校验身份与输入</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>业务代码发起数据库或其他异步 I/O</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>等待期间，事件循环可以推进其他已就绪的任务</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>I/O 完成后继续业务逻辑，构造响应</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>发送响应并处理日志、错误及资源释放</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>这里的并发主要依赖异步等待与任务调度，不能推导出“所有 JavaScript 都同时执行”。同一个事件循环线程上的长时间同步计算，会拖慢其他请求。</p><h2 id="四、继续连接-nestjs、数据库与部署" tabindex="-1">四、继续连接 NestJS、数据库与部署 <a class="header-anchor" href="#四、继续连接-nestjs、数据库与部署" aria-label="Permalink to &quot;四、继续连接 NestJS、数据库与部署&quot;">​</a></h2><ul><li><strong>理解框架分层</strong>：<a href="./../18nestjs/intro">NestJS 学习入口</a>，把 HTTP 请求处理扩展为模块、依赖注入与业务组织。</li><li><strong>认识认证边界</strong>：<a href="./../18nestjs/s_nestjs_12-authentication_jwt">认证、授权与 JWT</a>，理解凭证、权限、刷新与撤销，而不是手写密码学。</li><li><strong>认识请求顺序</strong>：<a href="/web-dev-handbook/学习自测/18nestjs/q_nestjs_7-request_lifecycle">NestJS 请求生命周期</a>，区分 Middleware、Guard、Pipe 和 Interceptor。</li><li><strong>理解持久化</strong>：<a href="./../19database/intro">数据库学习入口</a>，继续学习 SQL、事务与连接管理。</li><li><strong>理解进程与下线</strong>：<a href="./../20deploy/s_deploy_4-node_process">Node 进程管理与优雅停机</a>，理解多实例、在途请求排空与连接池关闭。</li></ul><h2 id="五、学习练习怎么记录" tabindex="-1">五、学习练习怎么记录？ <a class="header-anchor" href="#五、学习练习怎么记录" aria-label="Permalink to &quot;五、学习练习怎么记录？&quot;">​</a></h2><p>可以先完成四个小实验：流式复制文件、观察异步执行顺序、运行 HTTP 健康检查接口、编写 Koa 中间件。每次记录 <strong>Node 版本、代码位置、运行命令、预期结果、实际结果和异常场景</strong>。</p><p>示例不等于完整生产方案：小实验用于解释机制，真正的服务还需要业务约束、测试、可观测性与部署验证。实践记录可参考<a href="/web-dev-handbook/学习路线/index">学习路线</a>。</p><blockquote><p>来源：<a href="https://nodejs.org/en/learn/getting-started/introduction-to-nodejs" target="_blank" rel="noreferrer">Node.js 官方学习文档</a>、<a href="https://nodejs.org/docs/latest-v24.x/api/" target="_blank" rel="noreferrer">Node.js API</a>、<a href="https://docs.libuv.org/en/v1.x/design.html" target="_blank" rel="noreferrer">libuv 设计概览</a></p></blockquote>`,18)])])}const u=e(r,[["render",d]]);export{b as __pageData,u as default};
